package com.rulecraft.decisionops.simulation.api;
import com.rulecraft.decisionops.identity.security.CurrentUser;import com.rulecraft.decisionops.simulation.RegressionMatrixService;import com.rulecraft.decisionops.simulation.RegressionMatrixService.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/regression-matrices")
public class RegressionMatrixController {private final RegressionMatrixService service;public RegressionMatrixController(RegressionMatrixService service){this.service=service;}@GetMapping List<MatrixRunSummary> list(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication authentication){return service.list(CurrentUser.require(authentication),projectId,serviceId);}@GetMapping("/{runId}")MatrixRunView get(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID runId,Authentication authentication){return service.get(CurrentUser.require(authentication),projectId,serviceId,runId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)MatrixRunView execute(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody MatrixRunCommand body,Authentication authentication){return service.execute(CurrentUser.require(authentication),projectId,serviceId,body);}}
